import{_ as a,o as e,c as o,a3 as t}from"./chunks/framework.DdpBa4_E.js";const r="/ReadBooks/assets/image-003.CxWYwPuO.jpg",f=JSON.parse('{"title":"第1章：富爸爸，穷爸爸","description":"","frontmatter":{},"headers":[],"relativePath":"books/rich-dad-poor-dad/07-第一部分-课程.md","filePath":"books/rich-dad-poor-dad/07-第一部分-课程.md","lastUpdated":1794316978000}'),d={name:"books/rich-dad-poor-dad/07-第一部分-课程.md"};function s(_,p,i,n,c,l){return e(),o("div",null,[...p[0]||(p[0]=[t('<h1 id="第1章-富爸爸-穷爸爸" tabindex="-1">第1章：富爸爸，穷爸爸 <a class="header-anchor" href="#第1章-富爸爸-穷爸爸" aria-label="Permalink to &quot;第1章：富爸爸，穷爸爸&quot;">​</a></h1><p>我有两个爸爸，一个富，一个穷。一个受过良好的教育，聪明绝顶，拥有博士头衔，曾经没用两年就修完了4年的本科学业，随后又在斯坦福大学、芝加哥大学和西北大学深造，并都拿到了全额奖学金；但另一个却连八年级<a href="./07-第一部分-课程">(1)</a> 都没能念完。</p><p>两个爸爸的事业都相当成功，而且一辈子都非常勤奋。他们都有着丰厚的收入。然而其中一个人终其一生都在个人财务问题的泥沼中挣扎，另一个人则成了夏威夷最富有的人之一。一个爸爸去世后为家人、慈善机构和教堂留下了数千万美元的遗产，而另一个爸爸只留下一些待付的账单。</p><p>两个爸爸都是那种意志坚强、富有魅力、具有影响力的人。他们都曾给我建议，但建议的内容并不相同；他们也都深信教育的力量，但推荐给我的课程却从不一样。</p><p>如果我只有一个爸爸，那么对于他的建议我可以选择接受或者拒绝；但两个爸爸都给我建议，这就为我提供了一个在截然不同的观念间进行选择的机会，即选择富人的观念或穷人的观念。</p><p>对于富爸爸和穷爸爸的观念，我并不简单地接受或拒绝，我发现自己有更多的思考，在它们之间进行了比较，再为自己作出选择。</p><p>但问题是，在给我建议的时候，富爸爸还不算富有，穷爸爸也并不贫穷，他们的事业都刚刚起步，都在为钱和家庭而奋斗。然而，他们对钱的理解却迥然不同。</p><p>例如，一个爸爸会说：“贪财乃万恶之源。”而另一个爸爸却说：“贫穷才是万恶之本。”</p><p>当时我还只是一个小男孩，拥有两个对我同样有影响力的爸爸可不是一件好应付的事。我想成为一个听话的好孩子，但两个爸爸的话却完全不同。他们的观点正好相反，尤其在涉及金钱的问题上更是如此，这让我既好奇又迷惑。我开始花很多时间思考他们每个人讲的话。</p><p>我花了很多时间思考，问自己诸如“他为什么那样说”之类的问题，然后又对另一个爸爸的话提出同样的疑问。如果只是说“噢，他是对的，我同意”，或是说“他不知道自己在说什么”应该是很容易的事。相反，拥有两位我深爱的父亲，这促使我去思考，最终为自己选择其中一种思维方式。这一过程是我自己去选择而不是简单地接受或否定的过程，在后来的漫长岁月中被证明对我非常有益。</p><p>富人之所以越来越富，穷人之所以越来越穷，中产阶级之所以总是在债务的泥潭中挣扎，其中一个主要原因就是，他们对金钱的认识不是来自学校，而是来自家庭。大多数人都是从父母那儿了解钱是怎么回事的。关于金钱，贫穷的父母能够教给孩子们什么呢？他们只会说：“在学校里要好好学习喔。”结果，他们的孩子可能会以优异的成绩毕业，但同时也秉承了穷人的理财方式和思维习惯。这是孩子们在很小的时候就从父母那里学到的。</p><p>学校并没有开设有关“金钱”的课程。学校教育只专注于学术知识的传授和专业技能的培养，却忽视了理财技能的培训。所以众多精明的银行家、医生和会计师在学校时成绩优异，可还是要一辈子在财务问题上挣扎。美国岌岌可危的债务问题在很大程度上也应归因于那些政治家和政府官员们作出的财务决策，他们虽然受过高等教育，但很少甚至几乎没有接受过理财方面的培训。</p><p>我常常在想，新千年到来之后会是什么样子？当数百万人需要经济和医疗援助时该怎么办？当然，他们可以得到家人的支持和政府的救助。可是，当医疗保险和社会保险都用完时又该怎么办？如果我们继续把教孩子理财的重任交给那些濒于贫困边缘或已陷入贫困境地的父母，我们的国家又该怎么发展下去？</p><p>由于我有两位极具影响力的爸爸，所以我从他们两人身上都学到了很多东西。我不得不思考每个爸爸的建议，在我把这些建议付诸实际的同时，我认识到有一点很重要，那就是一个人的观念对他的一生影响巨大。例如，我的一个爸爸总是习惯说“我可付不起”，而另一个爸爸则禁止我们说这样的话，他坚持让我这样说：“我怎样才能付得起？”这两句话，一句是陈述句，另一句是疑问句。一句让你放弃，而另一句则促使你去想办法。我那个在不久之后就富起来的爸爸解释，当你下意识地说出“我付不起”的时候，你的大脑就会停止思考；而如果你自问“我怎样才能付得起”，则会让你的大脑动起来。当然，他的意思并不是让你把每件想要的东西都买到手，这里只是强调要不停地锻炼你的大脑——它是世界上最强大的“计算机”。富爸爸说：“我的大脑越用越活，大脑越活，我挣的钱就越多。”他认为，下意识地说“我可付不起”意味着精神上的懒惰。</p><p>虽然两个爸爸工作都很努力，但我注意到，在遇到钱的问题时，一个爸爸习惯于逃避，另一个爸爸则总是想办法解决问题。长此以往，其结果就是，一个爸爸的理财能力越来越弱，而另一个爸爸的理财能力则越来越强。这种结果类似于一个经常去健身房锻炼的人与一个总坐在沙发上看电视的人在体质上的不同变化。适当的体育锻炼可以增加获得健康的机会，同样，适当的脑力训练可以增加获得财富的机会。懒惰必定会让你的体质变弱、财富减少。</p><p>两个爸爸的观念完全不同。一个爸爸认为，富人应该多缴税去照顾那些相对不幸的人；另一个爸爸则说：“税是惩勤奖懒。”</p><p>一个爸爸劝我：“努力学习吧，那样你就能去好公司工作。”而另一个爸爸则说：“努力学习吧，那样你就能发现一家好公司并收购它。”</p><p>一个爸爸说：“我不富有，因为我有孩子。”而另一个爸爸则说：“我必须富有，因为我有孩子。”</p><p>一个爸爸提倡在餐桌上讨论钱和生意，而另一个爸爸则禁止在吃饭时谈论这些话题。</p><p>一个爸爸说：“当涉及钱的时候要小心，别去冒险。”而另一个爸爸则说：“要学会管理风险。”</p><p>一个爸爸认为“房子是最大的投资和资产”，而另一个爸爸则相信“房子是负债，如果你的房子是你最大的投资，你就有麻烦了”。</p><p>两个爸爸都会准时付账，但不同的是：一个预先支付账单，而另一个到限期才支付账单。</p><p>一个爸爸相信政府和公司会关心和满足人们的需求。他总是很关心加薪、退休政策、医疗补贴、病假、假期以及津贴这类事情。他有两个参军的叔叔，在服役20年后获得了退休金和终身保障，这让他深受影响。他很喜欢军队向退役人员发放医疗补贴和开办福利社的做法，也很喜欢大学里的终身聘任制。对他而言，职业保障和职位补贴有时甚至比职业本身更重要。他经常说：“我辛辛苦苦为政府工作，我有权享受这些待遇。”</p><p>另一个爸爸则信奉完全的经济自立，他反对这种“理所应当”的心理，认为正是这种心理造成了人们的软弱、贫穷。他特别重视理财的能力。</p><p>一个爸爸努力存钱，另一个爸爸则不断投资。</p><p>一个爸爸教我怎样去写一份让人印象深刻的简历，以便找到一份好工作；另一个爸爸则教我写下雄心勃勃的事业规划和财务计划，进而创造创业的机会。</p><p>作为两个意志坚定的爸爸的“杰作”，我有幸了解到不同的观念怎样带来不同的人生。我发现人们的思想确实可以决定他们的生活。</p><p>例如，我的穷爸爸总是说：“我永远也不会成为富人。”于是这句话就成了事实。而我的富爸爸恰恰相反，他总是把自己说成是一个富人。他会这样说：“我是一个富人，富人不会这么做。”甚至当一次严重的经济挫折使他一文不名后，他仍然把自己当做富人。他会这样安慰自己：“贫穷和破产的区别是：破产是暂时的，而贫穷是永久的。”</p><p>我的穷爸爸也会说“我对钱不感兴趣”或“钱对我来说并不重要”，而我的富爸爸则说“金钱就是力量”。</p><p>尽管思想的力量无法测量或评估，但当我还是一个孩子时，我就已经明确自己内心的想法，也知道如何表达自己。我注意到穷爸爸之所以穷不在于他挣钱的多少（尽管这也很重要），而在于他的想法和行为。因为拥有两个爸爸，我敏锐地觉察到要小心地选择和利用其中一种观念。我到底应该听谁的：是富爸爸还是穷爸爸？</p><p>尽管两个爸爸都高度重视教育和学习，但两人对于什么才是最应该学习的看法却不同。一个爸爸希望我努力学习，获得学位，找个工资高的好工作。他希望我能成为一名专业人士，例如：律师、会计师，或者去商学院读MBA。另一个爸爸则鼓励我学习成为富人，了解钱的运动规律并让钱为我工作。“我不为钱工作，”这句话他说了一遍又一遍，“我要让钱为我工作。”</p><p>在我9岁那年，我最终决定听从富爸爸的话并向他学习有关钱的知识。同时，我决定不听穷爸爸的，即使他拥有那么多大学学位。</p><h3 id="罗伯特·弗罗斯特的教诲" tabindex="-1">罗伯特·弗罗斯特的教诲 <a class="header-anchor" href="#罗伯特·弗罗斯特的教诲" aria-label="Permalink to &quot;罗伯特·弗罗斯特的教诲&quot;">​</a></h3><p>罗伯特·弗罗斯特是我最喜欢的诗人，他的许多诗我都很喜欢，不过最爱的还是下面这首“未选之路”。从诗中受到的启发我几乎每天都要用到：</p><p>未选之路<a href="./07-第一部分-课程">(2)</a></p><p>林中两路分，可惜难兼行。</p><p>游子久伫立，极目望一径。</p><p>蜿蜒复曲折，隐于丛林中。</p><p>我选另一途，合理亦公正。</p><p>草密人迹罕，正待人通行。</p><p>足迹踏过处，两路皆相同。</p><p>两路林中伸，落叶无人踪。</p><p>我选一路走，深知路无穷。</p><p>我疑从今后，能否转回程。</p><p>数十年之后，谈起常叹息。</p><p>林中两路分，一路人迹稀。</p><p>我独选此路，境遇乃相异。</p><p>——罗伯特·弗罗斯特（1916）</p><p>选择不同，命运也会不同。</p><p>这些年来，我时常回味这首诗。选择不接受受过高等教育的爸爸关于钱的态度和建议，这是一个痛苦的决定，但这个决定塑造了我的人生。</p><p>一旦决定了要听从谁的建议，我的关于金钱的教育就开始了。富爸爸教了我30多年，直到我39岁为止。他一直努力向我那愚笨的头脑灌输东西，当他意识到我已经懂得并完全理解了，就不再给我上课了。</p><p>钱是一种力量，但更有力量的是财商教育。钱来了又会去，但如果你了解钱是如何运动的，你就获得了驾驭它的力量，就能开始积累财富了。大多数人光想不干，原因是他们在接受学校教育时并没有掌握钱的运动规律，所以他们终生都在为钱工作。</p><p>我开始学习金钱这门课程时只有9岁，因此富爸爸教我的东西都非常简单。他把所有想教给我的东西说完、示范完，概括起来也只有6门主要的课程，在过去的30多年中，我们一直在重复和加强这些课程。本书就教授了这6门课程，我尽可能使它像当年富爸爸教我时那样简单。这些课程并不仅仅意味着提供答案，它们也是路标。无论这个充满不确定性和飞速变化的世界会发生什么事情，这些路标都能帮助你和你的孩子积累财富。</p><p><img src="'+r+'" alt="" loading="lazy"></p><p>————————————————————</p><p><a href="./07-第一部分-课程">(1)</a> 在美国大多数州义务教育的学制与我国不同，小学为5年，初中为3年，高中为4年。八年级即初中的最后一年。</p><p><a href="./07-第一部分-课程">(2)</a> 此诗为关山译。</p>',57)])])}const m=a(d,[["render",s]]);export{f as __pageData,m as default};
